package com.careerpilot.modules.assessment.controller;
import com.careerpilot.modules.assessment.dto.*;import com.careerpilot.modules.assessment.service.AssessmentService;import com.careerpilot.security.CurrentUser;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/assessment-attempts")
public class AssessmentAttemptController{private final AssessmentService service;public AssessmentAttemptController(AssessmentService service){this.service=service;}@GetMapping("/{id}")@Operation(summary="Get an owned attempt",description="Correct answers and explanations are included only after server-side submission.")public AttemptResponse get(@PathVariable UUID id){return service.get(CurrentUser.require(),id);}@PostMapping("/{id}/submit")@Operation(summary="Submit and deterministically grade an MCQ attempt")public AttemptResponse submit(@PathVariable UUID id,@Valid@RequestBody SubmitAttemptRequest request){return service.submit(CurrentUser.require(),id,request);}@GetMapping public List<AttemptSummaryResponse>history(){return service.history(CurrentUser.require());}@GetMapping("/latest")public AttemptSummaryResponse latest(){return service.latest(CurrentUser.require());}}
